function telegramReleaseCommand({ body, allowedChatId, allowedUserId }) {
  const message = body?.message,
    text = message?.text;
  if (typeof text !== "string" || !text.includes("/deploy")) return { run: false, tag: "skipped" };
  for (const [name, value] of Object.entries({ allowedChatId, allowedUserId }))
    if (typeof value !== "string" || !/^\-?\d{1,20}$/.test(value))
      throw new Error("Configure " + name + " as a numeric Telegram ID.");
  if (!Number.isSafeInteger(message?.chat?.id) || !Number.isSafeInteger(message?.from?.id))
    throw new Error("The command needs its Telegram chat and sender IDs.");
  if (String(message.chat.id) !== allowedChatId || String(message.from.id) !== allowedUserId)
    return { run: false, tag: "skipped" };
  const tag = text.split(" ")[1];
  if (typeof tag !== "string" || !tag.trim())
    throw new Error("The deploy message needs a nonempty second space-separated field.");
  return { run: true, tag };
}

return $input.all().map((item, index) => ({
  json: telegramReleaseCommand({
    body: item.json,
    allowedChatId: "YOUR_TELEGRAM_CHAT_ID",
    allowedUserId: "YOUR_TELEGRAM_USER_ID",
  }),
  pairedItem: { item: index },
}));

return $input.all().map((item, index) => {
  const tag = $("Check the authorized command").item.json.tag;
  if (
    !Number.isSafeInteger(item.json.id) ||
    item.json.id <= 0 ||
    item.json.tag_name !== tag ||
    item.json.draft !== false
  )
    throw new Error(
      "GitHub did not confirm the published release; inspect GitHub before replaying.",
    );
  return { json: { status: "published", release: item.json }, pairedItem: { item: index } };
});
